// Convierte las filas de la hoja en { id: unidades } y elige el origen permitido para CORS.
const unidades = {};
for (const i of $input.all()) {
  const id = String(i.json.id || '').trim();
  const n = parseInt(String(i.json.unidades ?? '').trim(), 10);
  if (id && Number.isFinite(n)) unidades[id] = Math.max(0, n);
}
const origin = String($('Stock desde la web').first().json.headers.origin || '');
const permitido = origin === 'https://marinascotelomarcos-blip.github.io' || /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin);
return [{ json: {
  origen: permitido ? origin : 'https://marinascotelomarcos-blip.github.io',
  cuerpo: { ejemplo: true, actualizado: $now.setZone('Europe/Madrid').toISO(), unidades }
} }];
